255	
256	        publishPlan(scheduleKey, key("REQ"));
257	        // 已发布不可重复发布（新幂等键）
258	        mvc.perform(post("/api/v1/plans/{key}/publish", scheduleKey)
259	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(key("REQ"))))
260	                .andExpect(status().isConflict());
261	
262	        cancelPlan(scheduleKey, key("REQ"));
263	        // 已取消不可发布、不可再取消
264	        mvc.perform(post("/api/v1/plans/{key}/publish", scheduleKey)
265	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(key("REQ"))))
266	                .andExpect(status().isConflict());
267	        mvc.perform(post("/api/v1/plans/{key}/cancel", scheduleKey)
268	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(key("REQ"))))
269	                .andExpect(status().isConflict());
270	    }
271	
272	    // ---------- 时隙冲突 422 ----------
273	
274	    @Test
275	    void publishRejectsTrainOverlapWithinPlan() throws Exception {
276	        String scheduleKey = key("SCH");
277	        String publishKey = key("REQ");
278	        createPlan(scheduleKey,
279	                occ("G1", key("SEC"), iso(8), iso(9)),
280	                occ("G1", key("SEC"), iso(8), iso(9)));
281	
282	        MvcResult result = mvc.perform(post("/api/v1/plans/{key}/publish", scheduleKey)
283	                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(publishKey)))
