    restricted BOOLEAN NOT NULL,
    version INT NOT NULL,
    updated_at BIGINT NOT NULL,
    PRIMARY KEY (section_id)
);
COMMENT ON TABLE rail_section_restriction IS '限制区段配置：区段是否限制危险品通行及配置版本；配置整体替换时版本逐区段递增';
