    // ---------- 发布联合校验 ----------

    @Test
    void separationInsufficientBlocksPublishWithActualRequiredDeficit() throws Exception {
        String categoryA = cat();
        String categoryB = cat();
        replaceConfig(List.of(rule(categoryA, categoryB, 3)), List.of());
